SELECT COALESCE(SUM(qty), 0) AS qty
FROM logistic_receives
WHERE product_id = #{itemId} AND sales_order_id = #{salesInvoiceId}

SELECT COALESCE(SUM(total_qty), 0) AS qty FROM ( SELECT SUM(COALESCE(qty, 0) + COALESCE(qty_free, 0)) AS total_qty FROM sales_order_details WHERE product_id = #{itemId} AND sales_order_id IN #{id}
UNION ALL
SELECT SUM(COALESCE(qty, 0) + COALESCE(qty_free, 0)) AS total_qty FROM sales_order_services WHERE service_id = #{itemId} AND sales_order_id IN #{id}
UNION ALL
SELECT SUM(COALESCE(qty, 0) + COALESCE(qty_free, 0)) AS total_qty FROM sales_order_miscs WHERE id = #{itemId} AND sales_order_id IN #{id} ) AS all_quantities

